import React, { useEffect, useMemo, useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, LineElement, PointElement, LinearScale, Tooltip, Legend, CategoryScale, type ChartData, type ChartOptions, type TooltipItem } from 'chart.js';
import katex from 'katex';
import 'katex/dist/katex.min.css';
import { calculateMetrics, calculatePD_Emax, calculateRMSE, maximumAbsoluteError, solveLogistic, solvePK_Euler, solvePK_Exact, solvePK_RK4, solveSIR, sirInvariants, validateParameters, validateSIR, type PKParams, type SIRParams } from './engine/math';
import { categoryFilters, modelRegistry, modelSources, type ModelDefinition } from './engine/models';
